ALTER TABLE "jobs"."catalogue_region" ADD CONSTRAINT "catalogue_region_key_check" CHECK ("jobs"."catalogue_region"."key" ~ '^[a-z][a-z0-9_]{1,47}$' and "jobs"."catalogue_region"."key" not in ('none', 'several', 'other'));